"""Check data against a data contract, and compare two versions of a contract.

Usage:
    python check_contract.py validate contract_v1.yaml data/visits.csv
    python check_contract.py diff contract_v1.yaml contract_v2.yaml
Both exit with status 1 when they find a problem, so a CI pipeline can stop on them.
"""
import math
import sys

import pandas as pd
import pandera.pandas as pa
import yaml

TYPES = {"string": str, "integer": int, "number": float, "date": pa.DateTime, "timestamp": pa.DateTime}


def load(path):
    with open(path, encoding="utf-8") as f:
        return yaml.safe_load(f)


def schema_from(contract):
    """Turn the contract's field list into a pandera schema."""
    columns = {}
    for field in contract["schema"]:
        checks = []
        if "allowed" in field:
            checks.append(pa.Check.isin(field["allowed"]))
        if "min" in field or "max" in field:
            checks.append(pa.Check.in_range(field.get("min", -math.inf), field.get("max", math.inf)))
        if "pattern" in field:
            checks.append(pa.Check.str_matches(field["pattern"]))
        required = field.get("required", False)
        columns[field["name"]] = pa.Column(TYPES[field["type"]], checks, required=required, nullable=not required,
                                           unique=field.get("unique", False))
    return pa.DataFrameSchema(columns, coerce=True)


def validate(contract, csv_path):
    text_fields = {f["name"]: "string" for f in contract["schema"] if f["type"] == "string"}
    data = pd.read_csv(csv_path, dtype=text_fields)
    print(f"Contract {contract['id']} {contract['version']}: checking {len(data)} rows of {csv_path}")
    try:
        schema_from(contract).validate(data, lazy=True)
    except pa.errors.SchemaErrors as err:
        cases = err.failure_cases
        for (column, check), group in cases.groupby(["column", "check"]):
            print(f"  FAIL {column}: {check}: {group['index'].nunique()} rows")
        return 1
    print("  every row meets the contract")
    return 0


def diff(old, new):
    """Classify each change from the consumers' side: SAFE if every batch valid under the new version is
    also valid under the old one, so consumers built on the old version keep working; otherwise BREAKING."""
    before = {f["name"]: f for f in old["schema"]}
    after = {f["name"]: f for f in new["schema"]}
    changes = []
    for name in sorted(before.keys() - after.keys()):
        changes.append(("BREAKING", f"{name}: removed (a rename is a removal plus an addition)"))
    for name in sorted(after.keys() - before.keys()):
        kind = "required" if after[name].get("required") else "optional"
        changes.append(("SAFE", f"{name}: added ({kind})"))
    for name in sorted(before.keys() & after.keys()):
        a, b = before[name], after[name]
        if a["type"] != b["type"]:
            changes.append(("BREAKING", f"{name}: type {a['type']} -> {b['type']}"))
        if a.get("required") and not b.get("required"):
            changes.append(("BREAKING", f"{name}: now optional, so consumers may receive nulls"))
        if b.get("required") and not a.get("required"):
            changes.append(("SAFE", f"{name}: now required"))
        # TODO: classify these changes too, with the same rule (could consumers now get data they don't expect?):
        #   allowed values: new values are BREAKING ("new allowed values [...]"); fewer values are SAFE
        #   min and max: a wider range is BREAKING ("range widened to lo..hi"); a narrower one SAFE ("range narrowed to lo..hi")
        #   unit: any change is BREAKING ("unit old -> new"), even though the type is the same
        #   pattern: any change is BREAKING ("pattern changed; review it by hand")
    for verdict, text in sorted(changes):
        print(f"{verdict:<9} {text}")
    major, minor, _ = (int(x) for x in old["version"].split("."))
    breaking = sum(verdict == "BREAKING" for verdict, _ in changes)
    expected = f"{major + 1}.0.0" if breaking else f"{major}.{minor + 1}.0"
    print(f"{breaking} breaking of {len(changes)} changes; the new version should be {expected}, "
          f"and it says {new['version']}")
    return 1 if breaking or new["version"] != expected else 0


def main():
    if len(sys.argv) != 4 or sys.argv[1] not in ("validate", "diff"):
        sys.exit(__doc__)
    if sys.argv[1] == "validate":
        sys.exit(validate(load(sys.argv[2]), sys.argv[3]))
    sys.exit(diff(load(sys.argv[2]), load(sys.argv[3])))


if __name__ == "__main__":
    main()

